mapper.update:
UPDATE proj_project_node_execution SET plan_version_id=#{query.newPlanVersionId}, contract_id=#{query.newContractId},
    version=version+1, updater=#{query.updater}, update_time=CURRENT_TIMESTAMP(3)
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND id=#{query.executionId}
  AND plan_version_id=#{query.oldPlanVersionId} AND contract_id=#{query.expectedContractId}
  AND version=#{query.expectedVersion} AND current_marker=1 AND status IN ('PENDING','ACTIVE') AND deleted=0

UPDATE proj_project_node_execution SET version=version+1, updater=#{query.actorId}, update_time=CURRENT_TIMESTAMP(3),
status='ACTIVE', admitted_at=COALESCE(admitted_at,#{query.occurredAt}), started_at=#{query.occurredAt}, started_plan_version_id=plan_version_id
submitted_at=#{query.occurredAt}, submitted_by=#{query.actorId}
status=CASE WHEN #{query.action}='COMPLETE' THEN 'DONE' ELSE 'TERMINATED' END, ended_at=#{query.occurredAt}, result_snapshot=#{query.evidence}
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND node_instance_id=#{query.taskId} AND contract_id=#{query.contractId} AND node_kind='TASK' AND current_marker=1 AND deleted=b'0' AND status IN ('PENDING','ACTIVE') AND started_at IS NULL AND started_at IS NOT NULL AND submitted_at IS NULL
